from save_review import save
save(1169,{2:'灭灵武器是一类由未知异形种族创造、被灰骑士战团采用的灵能武器。灰骑士究竟窃取了这项技术，还是由对方自愿交付，至今无人知晓；可以确定的是，它与帝国军械库中的其他武器截然不同。',4:'Grey Knight with Psilencer 配备灭灵武器的灰骑士',7:'灭灵武器通过引导、聚焦并放大使用者的灵能力量发动攻击。它设计独特，没有扳机；持有者须将灵能导入武器的约束核心，再由聚焦晶体将能量凝成一道纯净的蔚蓝色脉冲，足以使恶魔的实体形态失稳。',9:'Grey Knights Terminator with Psilencer 配备灭灵武器的灰骑士终结者',12:'灭灵加特林是威力远超普通型号的重型灭灵武器，体积过大，单名灰骑士无法使用，因此专供强大的涅墨西斯骇骑机甲装备。',14:'Gatling psilencer 灭灵加特林'}, {2:'与464篇既定Psilencer灭灵武器统一；原灭灵者为别名。异型改异形。',14:'同一Gatling psilencer此前图注为灭灵加特林，末图原“天罚加特林”不一致，统一。'},[('Psilencer','灭灵武器'),('Gatling Psilencer','灭灵加特林')],title='灭灵武器 Psilencer')
save(1170,{2:'“这是帝皇之剑，混沌的大敌。它已斩杀数千名你的同类，你也不过是这份战绩上新增的一笔。”',4:'领主指挥官罗保特·基里曼对恶魔卡兰玛尔所言',6:'帝皇之剑是一把烈焰缠绕的巨剑，由帝皇凭借高深的科学知识与亚空间技艺铸造而成。',10:'帝皇之剑的锻造方式使它成为混沌的克星，只有最强大的恶魔才可能承受其触碰而不被毁灭。它能让恶魔真正死去，而不只是将其放逐回亚空间。在大远征和荷鲁斯之乱期间，帝皇以此剑斩灭了数千只恶魔，甚至终结了叛变战帅荷鲁斯的生命。然而，在与儿子的最后一战中，帝皇也濒临死亡，只能被安置在黄金王座上，以维系重伤后的生命。宝剑则被收入鞘中，横放在帝皇膝上，历经一万年，直至第十三次黑色远征开始。',12:'掠夺者阿巴顿对帝国发动新一轮猛攻期间，原体罗保特·基里曼复苏。这位复仇之子执起父亲的武器，为拯救帝国而战；帝皇之剑此后成为他的主要武器。尽管如今持剑者已非帝皇，剑中仍留存着造物主浩瀚力量的一部分。基里曼因此表示，每次挥剑时都能感到父亲的存在；他相信，这件武器仍藏有唯有帝皇才知道如何唤醒的奥秘。'},
{10:'本段有关荷鲁斯之死、帝皇之剑长期存放位置的叙述按底稿保留，属于本条所采版本，不与后出的不同叙述擅自拼接；interred在黄金王座语境是安置维生，非死后安葬。'},[("Emperor's Sword",'帝皇之剑'),('Qaramar','卡兰玛尔')])
save(1171,{2:'生命链接是一件极其强大而危险的灵能剑遗物，从伊奥尼斯边区的战场上被寻回。在那里，来自不同战团的七名首席智库员献出生命，放逐了一大群奸奇恶魔。那场战斗留下的可怕灵能回响由此灌注剑中，使持有者每次挥击都能释放毁灭性的能量洪流。'},{2:'artefact是遗物，不是master-crafted精工；武器名称与1167统一生命链接，原别名生命纽带保留对照。'},[('Vinculum Vitae','生命链接'),('Eonis Verge','伊奥尼斯边区')],title='生命链接 Vinculum Vitae')
save(1172,{4:'这把古剑硕大无比，只有星际战士才能举起。它从荷鲁斯的战斗驳船复仇之魂号残骸中被寻回，是其舱室内所有出土遗物中，唯一未被混沌污染的物品。一些工匠猜测，帝皇曾亲自使用此剑，武器散发的光辉正是人类之主伟力的体现。无论真相如何，激战中的燃烧之刃都会炽烈燃烧，甚至足以熔化持剑战斗兄弟身上的陶钢盔甲。尽管如此，这件神圣遗物仍经常被投入战斗。'},{4:'底稿将复仇之魂号称战斗驳船且提到残骸，按原说法保留；不因此判定整艘舰船已被彻底摧毁，也不擅自等同帝皇之剑。'},[('Burning Blade','燃烧之刃')])
save(1173,{2:'鲁斯之矛是太空野狼战团的传奇遗物，曾由原体黎曼·鲁斯使用。人类帝皇称它为酒神之矛，它也被称为狼矛，另有一个隐秘名字——冈格尼尔。',7:'纷争时代，帝皇在自己的第一座地下堡垒中亲手铸造此矛，并将一部分力量灌注其中。它最初名为酒神之矛，与日神之矛是一对姊妹武器。它能“启迪”被刺中的人，向其揭示真相的某一面。',9:'火焰之轮战役结束后，帝皇在塞拉芬纳将此矛赐给鲁斯，以作嘉奖。鲁斯却因它的存在而感到不安，起初不愿带它作战；他时常把它“遗失”在战场上，或“忘记”在会议厅里，携带它也只是为了取悦帝皇。可无论他怎样设法摆脱它，长矛最终总会回到身边。在芬里斯，鲁斯见到了另一个自己的幻象，由此得知长矛的真正性质。他以矛刺向自己，看见了关于原体本质的真相。此后，鲁斯逐渐接受这件武器，并将其用于战斗。在特里索兰之战中，他与荷鲁斯决斗，以矛重创战帅，还使其一度恢复了部分理智与昔日光辉，洗去了许多在摩洛沾染的腐化。',11:'后来在雅兰特，第十三连听闻如今的太空野狼如此敬畏这件遗物，似乎觉得颇为好笑。而在荷鲁斯之乱期间的雅兰特之战中，鲁斯曾将长矛交给比约恩。',13:'大清洗期间，黎曼·鲁斯与千子原体红魔马格努斯交战，一度失利。狼主加姆夺过长矛，刺伤马格努斯，为鲁斯争取到击退叛徒的机会，却付出了自己的生命。此后，这颗星球以牺牲于此的狼主命名为加姆，长矛则在当地的鲁斯神殿中供奉了数千年。太空野狼的预言说，黎曼·鲁斯将在狼之时刻归来，回到加姆取回武器。然而，包括巫师马多克斯在内的一伙千子偷走了长矛，企图以仪式将原体从亚空间召入物质世界。狼主贝雷克·雷拳的大连打断了仪式：当时仍是血爪的拉格纳·黑鬃夺起鲁斯之矛，将其掷过亚空间传送门，刺中马格努斯的眼睛。仪式随之中止，传送门关闭，但鲁斯之矛也就此遗失在亚空间中。',15:'后来，马多克斯又用此矛举行仪式，企图令所有太空野狼都屈服于狼人的诅咒，借此毁灭战团、重创帝国。拉格纳与数名同袍进入恐惧之眼，抵达查瑞斯行星在亚空间中的镜像，并在第十三大连部分成员的帮助下，赶在损害无法挽回之前阻止了仪式。借助符文牧师“掠夺者”托瓦德与导航员加布里埃拉·贝利撒留的力量，拉格纳和幸存者返回查瑞斯，长矛也被送回加姆。',17:'芬里斯星系围攻战期间，埃吉尔·铁狼再次执起这支长矛，用它对抗马格努斯。',19:'据一些芬里斯部落的神官传述，鲁斯之矛是帝皇赐给黎曼·鲁斯的礼物。神话还说，虽然原体并不喜爱它，它却忠实效劳，蕴含多种力量：鲁斯每次掷出长矛，芬里斯天空都会闪过雷电；被矛触及的人，则会看清关于自身的真相。',22:'鲁斯之矛的另一名字冈格尼尔，与神话中奥丁的长矛同名。和神话里的冈格尼尔一样，它总会返回持有者手中。奥丁也曾如鲁斯一样，以矛刺伤自己，以求获知隐秘。'},
{2:'开头写Gungir，末段写Gungnir，保留英文异拼，中文统一冈格尼尔。',9:'英文先称never took it into battle，随后又说把它丢在战场上，存在表述张力；译文以起初不愿带它作战保留其抗拒态度，不据此另造时间线。',11:'英文将“如今”对遗物的态度与荷鲁斯之乱期间的赠矛相邻叙述，未明示前句年代，故不把二者强行合为同一次事件。',15:'would cause说明仪式拟造成的结果，原译写成已经摧毁战团、削弱帝国，误将未遂后果当作既成事实。'},[('Spear of Russ','鲁斯之矛'),('Wolfspear (weapon)','狼矛'),('Gungnir','冈格尼尔'),('Gungir','冈格尼尔'),('Seraphina','塞拉芬纳'),('Wheel of Fire campaign','火焰之轮战役'),('Battle of Trisolian','特里索兰之战'),('Garm (Wolf Lord)','加姆'),('Garm (planet)','加姆'),('Shrine of Russ','鲁斯神殿'),('Torvald the Reaver','掠夺者托瓦德'),('Gabriella Belisarius','加布里埃拉·贝利撒留'),('Egil Iron Wolf','埃吉尔·铁狼'),('Gothi','神官')])
save(1174,{2:'基因提取手枪是原铸星际战士药剂师使用的一种手枪，能够迅速而利落地穿透星际战士的动力盔甲；面对横冲直撞的欧克战争头目，它也能同样轻易地贯穿其头骨。',4:'Primaris Apothecary with Reductor Pistol 装备基因提取手枪的原铸药剂师'}, {2:'Reductor在药剂师器械语境采用既定基因提取器词根，非还原者组织名。完整武器名暂定待核。'},[('Reductor Pistol','基因提取手枪')],title='基因提取手枪 Reductor Pistol')
save(1175,{2:'考古科技手枪是源自黑暗科技时代的古老随身武器。这个类别包含多种攻击方式，既可能发射微型原子弹药，也可能从行星磁层汲取能量，射出灼热的致命光束。在大远征与荷鲁斯之乱期间，帝国军队和星际战士的高级指挥官经常将这类手枪作为随身副武器。'}, {2:'magnetosphere为磁层，不是辐射层；英文以projectiles统称弹药和射线，中文按后文具体形式概括为攻击方式。'},[('Archaeotech Pistol','考古科技手枪'),('Archaeotech Laspistol','考古科技激光手枪')])
